#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

// Destination-passing-style entry for the masked-softmax + dropout
// backward kernel. Per definition.json:
//   grad_output   : [batch_size, n_heads, seq_len, seq_len] fp32
//   p_attn        : [batch_size, n_heads, seq_len, seq_len] fp32
//   mask          : [batch_size, 1, seq_len, seq_len] bool
//   dropout_mask  : [batch_size, n_heads, seq_len, seq_len] bool
//   p_dropout     : scalar fp32 (passed as double, matching reference)
//   grad_scores   : [batch_size, n_heads, seq_len, seq_len] fp32 (DPS)
//
// No const axes pinned by definition.json — runtime checks reduce
// to cross-tensor shape coherence, following the runtime-check
// audit discipline.

void run(
    torch::Tensor grad_output,
    torch::Tensor p_attn,
    torch::Tensor mask,
    torch::Tensor dropout_mask,
    double p_dropout,
    torch::Tensor grad_scores
) {
    TORCH_CHECK(grad_output.is_cuda(), "grad_output must be CUDA");
    TORCH_CHECK(p_attn.is_cuda(), "p_attn must be CUDA");
    TORCH_CHECK(mask.is_cuda(), "mask must be CUDA");
    TORCH_CHECK(dropout_mask.is_cuda(), "dropout_mask must be CUDA");
    TORCH_CHECK(grad_scores.is_cuda(), "grad_scores must be CUDA");

    TORCH_CHECK(grad_output.dtype() == torch::kFloat32,
                "grad_output must be float32");
    TORCH_CHECK(p_attn.dtype() == torch::kFloat32,
                "p_attn must be float32");
    TORCH_CHECK(mask.dtype() == torch::kBool, "mask must be bool");
    TORCH_CHECK(dropout_mask.dtype() == torch::kBool,
                "dropout_mask must be bool");
    TORCH_CHECK(grad_scores.dtype() == torch::kFloat32,
                "grad_scores must be float32");

    TORCH_CHECK(grad_output.is_contiguous(),
                "grad_output must be contiguous");
    TORCH_CHECK(p_attn.is_contiguous(), "p_attn must be contiguous");
    TORCH_CHECK(mask.is_contiguous(), "mask must be contiguous");
    TORCH_CHECK(dropout_mask.is_contiguous(),
                "dropout_mask must be contiguous");
    TORCH_CHECK(grad_scores.is_contiguous(),
                "grad_scores must be contiguous");

    TORCH_CHECK(grad_output.dim() == 4,
                "grad_output must be 4D [B, H, T, T]");
    TORCH_CHECK(p_attn.dim() == 4, "p_attn must be 4D");
    TORCH_CHECK(mask.dim() == 4, "mask must be 4D [B, 1, T, T]");
    TORCH_CHECK(dropout_mask.dim() == 4, "dropout_mask must be 4D");
    TORCH_CHECK(grad_scores.dim() == 4, "grad_scores must be 4D");

    const int64_t B = grad_output.size(0);
    const int64_t H = grad_output.size(1);
    const int64_t T1 = grad_output.size(2);
    const int64_t T2 = grad_output.size(3);
    TORCH_CHECK(T1 == T2, "grad_output last two dims must be equal "
                "(both = seq_len); got ", T1, " vs ", T2);

    TORCH_CHECK(p_attn.sizes() == grad_output.sizes(),
                "p_attn must have the same shape as grad_output");
    TORCH_CHECK(dropout_mask.sizes() == grad_output.sizes(),
                "dropout_mask must have the same shape as grad_output");
    TORCH_CHECK(grad_scores.sizes() == grad_output.sizes(),
                "grad_scores must have the same shape as grad_output");
    TORCH_CHECK(mask.size(0) == B && mask.size(1) == 1 &&
                mask.size(2) == T1 && mask.size(3) == T1,
                "mask must be [B, 1, T, T] matching grad_output's "
                "B and T");

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_066_masked_softmax_with_attention_dropout_backward_launcher(
        grad_output, p_attn, mask, dropout_mask, p_dropout,
        grad_scores, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "fp32 masked-softmax + dropout backward: per-row CTA "
        "(Grid (B, H, T)) with warp+block reduction over T, then "
        "per-element write with mask gating. Destination-passing "
        "style; grad_scores pre-allocated.");
}

#include "kernel.h"

#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

// fp32 masked-softmax + dropout backward in one per-row CTA kernel.
//
// Algorithm (matching the reference's three-link chain):
//   (a) dropout backward:
//       if p_dropout > 0: grad_softmax_output[j] = grad_output[j]
//                         * dropout_mask[j] * (1 / (1 - p_dropout))
//       else: grad_softmax_output[j] = grad_output[j]
//   (b) softmax backward:
//       sum_term = sum_j (p_attn[j] * grad_softmax_output[j])
//       grad_softmax_input[j] = p_attn[j] * (grad_softmax_output[j] - sum_term)
//   (c) masked_fill backward:
//       grad_scores[j] = mask[j] ? grad_softmax_input[j] : 0
//
// Kernel topology:
//   * Grid (B, H, T). One CTA per (b, h, t) row.
//   * BLOCK_THREADS = 256 (8 warps of 32 lanes); stride-loop over
//     the row length T (which can exceed 256).
//   * Each thread accumulates a fp32 partial sum across its stride
//     of (b, h, t, j). Warp-shuffle reduce within each warp; cross-
//     warp tree reduce via shared memory; thread 0 broadcasts the
//     final sum_term back through shared memory.
//   * Pass 1 reads grad_output[j] + dropout_mask[j] + p_attn[j]
//     and accumulates partial sum; pass 2 reads grad_output[j] +
//     dropout_mask[j] + p_attn[j] + mask[j] again to compute the
//     final grad_scores[j]. The two passes are necessary because
//     sum_term must be known before computing grad_scores[j].
//
// Note: mask is `[B, 1, T, T]`, which broadcasts across the H axis.
// The mask offset for (b, h, t, j) is `(b * 1 + 0) * T * T + t * T + j`
// = `b * T * T + t * T + j`.

namespace {

constexpr int kBlockThreads = 256;
constexpr int kWarpSize = 32;
constexpr int kNumWarps = kBlockThreads / kWarpSize;  // 8

__device__ __forceinline__ float warp_reduce_sum(float v) {
    #pragma unroll
    for (int off = kWarpSize / 2; off > 0; off >>= 1) {
        v += __shfl_xor_sync(0xffffffff, v, off);
    }
    return v;
}

__global__ void __launch_bounds__(kBlockThreads, 4) k_masked_softmax_dropout_bwd(
    const float* __restrict__ grad_output,
    const float* __restrict__ p_attn,
    const bool* __restrict__ mask,
    const bool* __restrict__ dropout_mask,
    float inv_keep_prob,        // 1.0 / (1.0 - p_dropout) if p_dropout > 0 else 1.0
    bool dropout_active,
    float* __restrict__ grad_scores,
    int H,
    int T
) {
    const int b = blockIdx.x;
    const int h = blockIdx.y;
    const int t = blockIdx.z;
    const int tid = threadIdx.x;

    const size_t row_offset = ((size_t)b * H + h) * T * T + (size_t)t * T;
    const size_t mask_row_offset = ((size_t)b * T + t) * T;  // mask is [B, 1, T, T]

    const float* __restrict__ grad_out_row = grad_output + row_offset;
    const float* __restrict__ p_attn_row = p_attn + row_offset;
    const bool* __restrict__ drop_row = dropout_mask + row_offset;
    const bool* __restrict__ mask_row = mask + mask_row_offset;
    float* __restrict__ grad_score_row = grad_scores + row_offset;

    float partial = 0.0f;
    for (int j = tid; j < T; j += kBlockThreads) {
        float gso = grad_out_row[j];
        if (dropout_active) {
            gso *= (drop_row[j] ? inv_keep_prob : 0.0f);
        }
        partial += p_attn_row[j] * gso;
    }

    partial = warp_reduce_sum(partial);

    __shared__ float warp_sums[kNumWarps];
    const int warp_id = tid / kWarpSize;
    const int lane = tid & (kWarpSize - 1);
    if (lane == 0) {
        warp_sums[warp_id] = partial;
    }
    __syncthreads();

    __shared__ float s_sum_term;
    if (tid == 0) {
        float total = 0.0f;
        #pragma unroll
        for (int w = 0; w < kNumWarps; ++w) {
            total += warp_sums[w];
        }
        s_sum_term = total;
    }
    __syncthreads();

    const float sum_term = s_sum_term;

    for (int j = tid; j < T; j += kBlockThreads) {
        float gso = grad_out_row[j];
        if (dropout_active) {
            gso *= (drop_row[j] ? inv_keep_prob : 0.0f);
        }
        const float grad_softmax_input = p_attn_row[j] * (gso - sum_term);
        grad_score_row[j] = mask_row[j] ? grad_softmax_input : 0.0f;
    }
}

}  // namespace

void problem_066_masked_softmax_with_attention_dropout_backward_launcher(
    const torch::Tensor& grad_output,
    const torch::Tensor& p_attn,
    const torch::Tensor& mask,
    const torch::Tensor& dropout_mask,
    double p_dropout,
    torch::Tensor& grad_scores,
    cudaStream_t stream
) {
    const int B = static_cast<int>(grad_output.size(0));
    const int H = static_cast<int>(grad_output.size(1));
    const int T = static_cast<int>(grad_output.size(2));

    const float p_drop_f32 = static_cast<float>(p_dropout);
    const bool dropout_active = p_drop_f32 > 0.0f;
    const float inv_keep_prob = dropout_active ? (1.0f / (1.0f - p_drop_f32)) : 1.0f;

    dim3 grid(B, H, T);
    dim3 block(kBlockThreads);

    k_masked_softmax_dropout_bwd<<<grid, block, 0, stream>>>(
        grad_output.data_ptr<float>(),
        p_attn.data_ptr<float>(),
        mask.data_ptr<bool>(),
        dropout_mask.data_ptr<bool>(),
        inv_keep_prob,
        dropout_active,
        grad_scores.data_ptr<float>(),
        H, T
    );

    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "problem_066 masked-softmax dropout backward kernel launch failed");
}

#pragma once

#include <torch/extension.h>
#include <cuda_runtime.h>

// Host launcher for the masked-softmax + dropout backward kernel:
//   grad_softmax_output[j] = grad_output[j] * dropout_mask[j] / (1 - p_dropout)
//   sum_term = sum_j (p_attn[j] * grad_softmax_output[j])
//   grad_softmax_input[j] = p_attn[j] * (grad_softmax_output[j] - sum_term)
//   grad_scores[j] = mask[j] ? grad_softmax_input[j] : 0
// where j indexes the last (softmax) dim of length T = seq_len.
//
// Tensors:
//   grad_output  : [B, H, T, T] fp32
//   p_attn       : [B, H, T, T] fp32
//   mask         : [B, 1, T, T] bool
//   dropout_mask : [B, H, T, T] bool
//   p_dropout    : scalar fp32 (0.0 means "no dropout"; passes grad unchanged)
//   grad_scores  : [B, H, T, T] fp32 (DPS; pre-allocated)
//
// Per-row CTA topology: Grid (B, H, T); each CTA owns one row of T
// columns. No const axes are pinned by definition.json.
void problem_066_masked_softmax_with_attention_dropout_backward_launcher(
    const torch::Tensor& grad_output,
    const torch::Tensor& p_attn,
    const torch::Tensor& mask,
    const torch::Tensor& dropout_mask,
    double p_dropout,
    torch::Tensor& grad_scores,
    cudaStream_t stream);
